        bots: [["Weet net hoe het paard springt.", "Hoi! Is het paardje degene die springt?", "Wacht, heb ik gewonnen? Joepie!", "Goede partij! Jij bent echt goed."], ["Duwt graag pionnen naar voren. Allemaal.", "Pionnen vooruit! Dat is het hele plan.", "Mijn pionnen hebben het gedaan!", "Volgende keer duw ik nog meer pionnen."], ["Ziet weleens een vrij stuk staan.", "Laat een stuk hangen en het is van mij.", "Ik zei toch dat ik iets zou vinden.", "Oké, je hebt me. Goed gespeeld."], ["Nieuw bij de club, een beetje opvliegend.", "Laten we netjes spelen. Geen domme blunders.", "Zo doe je dat.", "Hmpf. Goed gespeeld, denk ik."], ["Kent haar openingen, vergeet soms haar dame.", "Ik heb de hele week openingen gestudeerd. Klaar?", "De theorie wint weer.", "Mijn voorbereiding is op. Goede partij."], ["Ziet snel combinaties. Eindspelen minder.", "Pas op voor vorken. Ik ben dol op vorken.", "Tactiek liegt niet.", "Jij rekende beter. Respect."], ["Straft losse stukken genadeloos af.", "Elk los stuk is een cadeautje voor mij.", "Losse stukken vallen.", "Heel solide. Ik vond geen weg naar binnen."], ["Rekent diep en speelt op winst.", "Ik speel niet op remise.", "Precies tot het einde.", "Indrukwekkend. Verdiend."], ["Geduldig, precies, blundert bijna nooit.", "Neem je tijd. Ik neem de mijne.", "Kleine voordelen tellen op.", "Uitstekende partij. Echt."], ["De eindbaas. Geef alles.", "Je hebt de top bereikt. Eens kijken waarom.", "Zoals verwacht.", "Opmerkelijk. Weinigen komen langs mij."]],
