  P.textContent = "#colorBanner{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%) scale(.9);z-index:20;display:flex;align-items:center;gap:10px;padding:12px 20px;border-radius:14px;background:rgba(14,19,22,.9);color:#fff;font-weight:800;font-size:18px;box-shadow:0 10px 30px rgba(0,0,0,.4);opacity:0;pointer-events:none;transition:opacity .25s,transform .25s;white-space:nowrap}#colorBanner.show{opacity:1;transform:translate(-50%,-50%) scale(1)}#colorBanner i{width:34px;height:34px;background-size:contain;background-repeat:no-repeat;background-position:center}#flipPill{position:absolute;left:50%;top:8px;transform:translateX(-50%);z-index:15;border:0;border-radius:999px;padding:6px 12px;background:rgba(14,19,22,.85);color:#fff;font:inherit;font-size:13px;font-weight:800;box-shadow:0 4px 12px rgba(0,0,0,.35);cursor:pointer}#flipPill span{color:var(--accent)}#flipPill[hidden]{display:none}", document.head.appendChild(P), c.refresh();
